'use strict';
// Presentation only. No network, persistence, authentication or actual pricing.
const OWNER='idan.caliber@gmail.com';
const state={owner:false,partner:1,selected:new Set(['one-suv','mm-suv']),recipient:'partner',tour:-1,booked:false,manual:false,request:false,expired:false,filter:'all',trip:{pickup:'קרקוב · שדה תעופה',dropoff:'קרקוב · שדה תעופה',from:'01.12.2026',to:'05.12.2026',time:'10:00',returnTime:'10:00'},driver:'',invoice:''};
const names={1:'שותף לדוגמה',2:'שותף נוסף לדוגמה'};
const choices=[
 {id:'one-suv',company:'One Rent',group:'SUV Premium medium AT',models:'Volvo XC60, Lexus NX, Audi Q5 או דומה',categories:[10]},
 {id:'mm-suv',company:'MM Cars',group:'PREMIUM SUV',models:'Volvo XC60 או דומה',categories:[10]},
 {id:'carfree-d',company:'CarFree',group:'D Automatic',models:'הדגמים יוצגו מהקבוצה שבמחירון',categories:[3]},
 {id:'kaizen-f',company:'Kaizen Rent',group:'SUV Aut big · FFAR',models:'הדגמים יוצגו מהקבוצה שבמחירון',categories:[7,6]}
];
const categories=['רכב קטן','רכב סטנדרטי סדאן','רכב סטיישן','רכב משפחתי / מנהלים גדול, סדאן','רכב היברידי','קראסאובר SUV קטן','קראסאובר SUV בינוני','קראסאובר SUV גדול','רכב פרמיום סדאן','רכב פרמיום SUV קטן','רכב פרמיום SUV בינוני','רכב פרמיום SUV גדול','רכב של 7 מקומות','רכב 8/9 מקומות'];
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,color='')=>`<span class="status ${color}">${text}</span>`;
const button=(text,route,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${route}">${text}</a>`;
const steps=n=>`<ol class="steps">${['פרטי הנסיעה','בחירת רכבים','שליחת ההצעה','הזמנה ומעקב'].map((s,i)=>`<li class="${i===n?'active':''}">${i+1} · ${s}</li>`).join('')}</ol>`;
const heading=(eyebrow,title,subtitle,action='')=>`<div class="page-top"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
const field=(label,name,value='',type='text',required=false)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
function login(){return `<div class="split"><section class="panel"><span class="eyebrow">גישה אישית שנפתחה עבורכם על ידי עידן</span><h1>ברוכים הבאים למרחב שלכם.</h1><p class="muted">ההצעות, ההזמנות והתנאים שלכם — במקום אחד.</p><form id="login-form"><div style="margin:24px 0">${field('מייל / שם משתמש','username','','text',true)}</div>${field('סיסמה אישית','password','','password',true)}<div class="actions"><a href="#manual" class="small">צריכים עזרה בכניסה?</a><button class="button primary">כניסה למרחב ←</button></div></form><p class="small muted">הדגמה בלבד. אל תזינו סיסמה אמיתית. אין הרשמה עצמאית.</p></section><aside class="side-note"><img src="idan-portrait.jpg" alt="עידן"><h3>העבודה עצמאית. הקשר אישי.</h3><p>מכינים ושולחים הצעות בעצמכם. אם משהו מורכב, אני כאן כדי לעזור.</p></aside></div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function showDialog(content){$('#dialog-content').innerHTML=content;if(typeof $('#dialog').showModal==='function')$('#dialog').showModal();else $('#dialog').setAttribute('open','');}
function tripSummary(){const t=state.trip;return `<div class="summary-trip"><div><span>קבלה</span>${esc(t.pickup)} · <bdi>${esc(t.from)}, ${esc(t.time)}</bdi></div><div><span>החזרה</span>${esc(t.dropoff)} · <bdi>${esc(t.to)}, ${esc(t.returnTime)}</bdi></div></div>`;}
function comparison(){return `<details class="company-compare"><summary>איזו חברה מתאימה ללקוח? השוואה קצרה</summary><div class="table-wrap"><table><thead><tr><th>מה חשוב לדעת</th><th>One Rent</th><th>CarFree</th><th>MM Cars</th><th>Kaizen Rent</th></tr></thead><tbody><tr><td>רכבים עד שנתיים</td><td>כן</td><td>כן</td><td>כן</td><td>לפי ההצעה</td></tr><tr><td>דלפקים ברוב שדות התעופה</td><td>יש לבדוק</td><td>כן</td><td>יש לבדוק</td><td>כן</td></tr><tr><td>קבלה בטרמינל</td><td>כן</td><td>כן</td><td>כן</td><td>כן</td></tr><tr><td>החזרה בטרמינל</td><td>תלוי בשדה</td><td>תמיד</td><td>תלוי בשדה</td><td>תמיד</td></tr><tr><td>מדיניות דלק</td><td>מלא למלא</td><td>כמו שקיבלתם</td><td>מלא למלא</td><td>מלא למלא</td></tr><tr><td>GPS להזמנה</td><td>לא</td><td>כן</td><td>כן</td><td>כן</td></tr></tbody></table></div><p class="hint green">בכל החברות: ביטוח מלא עם ביטול השתתפות עצמית, כולל גניבה, שמשות וגלגלים, בכפוף לתנאי ההשכרה; צמיגים לעונה ואפשרות להזמין שרשראות.</p></details>`;}
function history(type='all'){
 const rows=[];
 if(type!=='bookings')rows.push(`<tr><td><strong>DEMO-Q-0141</strong><small>לקוח לדוגמה</small></td><td>קרקוב · 01.12–05.12</td><td>2 אפשרויות</td><td>${badge('הצעה פעילה','green')}</td><td><a href="#review">פתיחת ההצעה ←</a></td></tr>`);
 if(type!=='quotes' && state.partner===1)rows.push(`<tr><td><strong>DEMO-R-0082</strong><small>נהג לדוגמה</small></td><td>ורשה · 12.12–16.12</td><td>CarFree</td><td>${badge('מאושרת','green')}</td><td><a href="#detail">צפייה בהזמנה ←</a></td></tr>`);
 if(state.booked&&state.partner===state.bookingPartner&&type!=='quotes')rows.unshift(`<tr><td><strong>DEMO-R-0083</strong><small>${esc(state.driver||'נהג לדוגמה')}</small></td><td>${esc(state.trip.pickup)}</td><td>${esc(state.bookingCompany||'One Rent')}</td><td>${badge('ממתינה לאישור','gold')}</td><td><a href="#detail-new">צפייה בהזמנה ←</a></td></tr>`);
 return `<div class="table-wrap"><table><thead><tr><th>מספר ולקוח</th><th>הנסיעה</th><th>חברה / אפשרויות</th><th>מצב</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
}
function home(){return `<section class="hero"><div><span class="eyebrow">הקשר שלכם עם חברות ההשכרה, במקום אחד</span><h1>שלום, ${names[state.partner]}.</h1><p>מכינים הצעה, בוחרים רכב ומזמינים. עידן מלווה אתכם לאורך הדרך — גם כשצריך לשנות משהו.</p>${button('＋ מתחילים הצעה חדשה','trip',true)}</div><img src="idan-portrait.jpg" alt="עידן" width="110" height="110"></section><div class="stats"><div class="stat"><b>1</b><span>הצעה פעילה</span></div><div class="stat"><b>${state.booked?'1':'0'}</b><span>ממתינות לאישור</span></div><div class="stat"><b>${state.partner===1?1:0}</b><span>הזמנה מאושרת</span></div></div><section class="panel"><div class="panel-heading"><h2>ממשיכים מאיפה שעצרתם</h2><a href="#quotes" class="small">כל ההצעות וההזמנות ←</a></div>${history()}</section><section class="panel"><div class="row between"><div><h3>הפרטים שלכם כבר כאן.</h3><p class="muted small">המייל, הטלפון והתנאים שסוכמו עם עידן נשמרים מראש. אין צורך להזין אותם בכל פנייה.</p></div><button class="quiet" data-action="profile">צפייה בפרטים</button></div></section>`;}
function trip(){const t=state.trip;const times=Array.from({length:48},(_,i)=>`${String(Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`);const timeSelect=(name,value)=>`<select name="${name}">${times.map(s=>`<option ${value===s?'selected':''}>${s}</option>`).join('')}</select>`;return `${steps(0)}${heading('הצעה חדשה','קודם, פרטי הנסיעה.','הפרטים שתמלאו ישמשו את כל החברות — פעם אחת בלבד.')}<form id="trip-form"><section class="panel"><div class="form-grid"><label>קבלת הרכב<select name="pickup"><option>${esc(t.pickup)}</option><option>ורשה · שדה תעופה</option><option>ורשה · מלון / כתובת</option><option>פראג · שדה תעופה</option></select></label><label>החזרת הרכב<select name="dropoff"><option>${esc(t.dropoff)}</option><option>ורשה · שדה תעופה</option><option>ורשה · מלון / כתובת</option><option>פראג · שדה תעופה</option></select></label></div><div class="form-grid four" style="margin-top:18px">${field('תאריך קבלה · יום.חודש.שנה','from',t.from,'text',true)}<label>שעת קבלה${timeSelect('time',t.time)}</label>${field('תאריך החזרה · יום.חודש.שנה','to',t.to,'text',true)}<label>שעת החזרה${timeSelect('returnTime',t.returnTime)}</label></div><div class="hint">כל הזמנים לפי השעה המקומית. טיסה בשעה מאוחרת? נחשב את השירות לפי פרטי הנסיעה.</div><div class="form-grid"><label>תיבת הילוכים<select name="transmission"><option>אוטומטית</option><option>ידנית</option><option>אין העדפה</option></select></label><label>יציאה למדינות נוספות<select id="cross-border" name="crossBorder"><option value="no">לא</option><option value="yes">כן — אציין את כל המדינות</option></select></label></div><div id="countries-wrap" hidden style="margin-top:16px">${field('מדינות יעד ומעבר','countries','','text')}<p class="small muted">נבדוק אישור יציאה, כיסוי, גרירה ורכב חלופי בהתאם לחברה.</p></div></section><section class="panel"><h2>בדיקה קצרה, כדי שלא יהיו הפתעות.</h2><div class="declarations"><label class="check"><input type="checkbox" name="driverOk" checked><span>כל הנהגים מעל גיל 24, עם רישיון מעל שנה<small>אם לא — שנו את הסימון. נחשב תוספת לפי הכללים הידועים או נעביר לבדיקה.</small></span></label><label class="check"><input type="checkbox" name="cardOk" checked><span>יש כרטיס אשראי על שם הנהג</span></label><label class="check"><input type="checkbox" name="borderOk" checked><span>ידוע לי שחובה לציין יציאה מחוץ למדינת ההשכרה</span></label></div><details><summary>תוספות והערות לנסיעה</summary><div class="form-grid" style="margin-top:16px"><label>כיסאות / בוסטרים<select name="seats"><option>ללא</option><option>1</option><option>2</option><option>3</option></select></label><label>מספר נהגים<select name="drivers"><option>1</option><option>2</option><option>3</option></select></label></div><label class="check"><input type="checkbox" name="chains">שרשראות שלג</label><label>מה עוד חשוב לדעת?<textarea name="notes" rows="2"></textarea></label></details></section><div class="actions">${button('שמירה וחזרה למרחב','home')}<button class="button primary">ממשיכים לבחירת רכבים ←</button></div></form>`;}
function options(){return `${steps(1)}${heading('הבחירה שלכם','מה מתאים ללקוח?','אפשר לשלב אפשרויות מכמה קטגוריות וחברות באותה הצעה.','<a class="small" href="#trip">עריכת הנסיעה</a>')}${tripSummary()}${comparison().replace('<details ', '<details open ')}<p class="hint gold">תצוגת עיצוב: אין כאן מחירים מומצאים. בגרסה המחוברת יוצגו המחירים המקוריים מאותו מחשבון שמשמש את עידן.</p>${categories.map((name,index)=>{const rows=choices.filter(o=>o.categories.includes(index));return `<details class="category" ${index===10?'open':''}><summary>${name}<span>${rows.length?rows.length+' אפשרויות להמחשה':'יוצג לפי זמינות המחירון'} ＋</span></summary><div class="table-wrap">${rows.length?`<table><thead><tr><th></th><th>חברה</th><th>קבוצה ודגמים מייצגים</th><th>מחיר לכל התקופה</th></tr></thead><tbody>${rows.map(o=>`<tr><td><input aria-label="בחירת ${o.company} ${o.group}" type="checkbox" data-pick="${o.id}" data-category="${index}" ${state.selected.has(o.id)?'checked':''}></td><td><strong>${o.company}</strong></td><td>${o.group}<div class="model">${o.models}</div><span data-already="${o.id}" data-category="${index}" class="selected-note" hidden>כבר נבחר בקטגוריה אחרת</span></td><td class="price-placeholder">לפי המחירון</td></tr>`).join('')}</tbody></table>`:'<p class="muted small" style="padding:0 18px">האפשרויות יוצגו כאן לאחר חיבור למחירון. לא הומצאו קבוצות או מחירים לצורך העיצוב.</p>'}</div></details>`;}).join('')}<div class="hint">דגם הרכב מייצג את הקבוצה. ההזמנה היא לפי קבוצה, בכפוף לאישור חברת ההשכרה.</div><div class="selection-bar"><div><b id="selected-count">${state.selected.size} אפשרויות נבחרו</b><small>כל קבוצה מופיעה פעם אחת בהצעה.</small></div><button class="button" data-action="review">ממשיכים להכנת ההצעה ←</button></div>`;}
function review(){const selected=choices.filter(o=>state.selected.has(o.id));return `${heading('הצעת מחיר · DEMO-Q-0141','איזו אפשרות הלקוח בחר?','כל האפשרויות נשמרו כאן. להזמנה, לחצו על הכפתור של הרכב שנבחר.','<a class="button" href="#options">עריכת ההצעה</a>')}${tripSummary()}<div class="offer-help"><strong>להפוך הצעה להזמנה — 3 צעדים פשוטים</strong><span>1. בוחרים אפשרות כאן</span><span>2. משלימים את פרטי הנהגים</span><span>3. בודקים ושולחים לחברה</span></div><div class="hint green">מחיר ההצעה נשמר 7 ימים. לאחר מכן הוא תקף כל עוד לא פורסם מחירון חדש של אותה חברה.</div>${selected.map((o,i)=>`<section class="saved-option"><div class="saved-option-heading"><span class="option-number">${i+1}</span><div><span class="small muted">אפשרות ${i+1} בהצעה</span><h2>${o.company} · ${o.group}</h2><p class="model">${o.models}</p></div></div><div class="saved-option-details"><div><span>מחיר לכל התקופה</span><strong>לפי המחירון</strong></div><div><span>פיקדון</span><strong>מופיע בהצעה המחושבת</strong></div><div><span>כלול</span><strong>ביטוח מלא עם ביטול השתתפות</strong></div></div>${state.expired&&o.id==='one-suv'?'<p class="hint gold">מחירון One Rent עודכן אחרי תום 7 הימים. נדרש חישוב חדש ואישור מחיר לפני הזמנה.</p>':''}<div class="option-order-action"><span class="small muted">זה הרכב שהלקוח בחר?</span><button class="button primary" data-action="book-option" data-option="${o.id}">בחירת אפשרות ${i+1} ויצירת הזמנה ←</button></div></section>`).join('')||'<section class="panel"><p>עדיין לא נבחרו אפשרויות.</p><a href="#options">בחירת רכבים ←</a></section>'}<details class="panel offer-mail"><summary>שליחת ההצעה במייל / שליחה חוזרת</summary><p class="small muted" style="margin-top:14px">שליחת הצעה אינה יצירת הזמנה. אפשר לשלוח את כל האפשרויות ללקוח.</p><form id="send-form">${field('שם הלקוח שעבורו ההצעה','customer','לקוח לדוגמה','text',true)}<label class="check"><input type="radio" name="recipient" value="partner" checked>רק אליי, עם העתק לעידן</label><label class="check"><input type="radio" name="recipient" value="both">אליי וללקוח, עם העתק לעידן</label><div id="client-email" hidden>${field('מייל הלקוח','clientEmail','','email')}</div><p class="small muted">הכתובת שלכם כבר שמורה: <bdi>partner@example.invalid</bdi></p><div class="email-preview"><strong>סימון ברור בכל מייל</strong><p><bdi>[PARTNER · ${names[state.partner]}] הצעת רכב</bdi></p><p>העתק קבוע לעידן: <bdi>${OWNER}</bdi></p></div><button class="button primary" style="margin-top:18px">שליחת ההצעה במייל</button></form></details><div class="row between"><a href="#quotes">חזרה להצעות שלי</a><button class="quiet" data-action="expiry">הדמיית עדכון מחירון לאחר 7 ימים</button></div>`;}
function bookingForm(){return `${steps(3)}${heading('הופכים אפשרות להזמנה','עוד כמה פרטים — ושולחים לחברה.','הפרטים נרשמים בתוכנית, ועידן מקבל העתק אוטומטי.')}${tripSummary()}<form id="book-form"><section class="panel">${selectedBookingSummary()}<h2>פרטי הנהג</h2><div class="form-grid">${field('שם מלא באנגלית, כפי שמופיע במסמכים','driver',state.driver,'text',true)}${field('טלפון','phone','','tel',true)}${field('מייל איש קשר','email','','email',true)}${field('מספר טיסה, אם יש','flight')}</div><label class="check"><input id="additional-driver" type="checkbox">הוספת נהג נוסף</label><div id="second-driver" hidden>${field('שם הנהג הנוסף באנגלית','secondDriver')}</div><label class="check"><input type="checkbox" id="invoice-toggle">נדרש אינווייס / חשבונית עם פרטים מיוחדים</label><div id="invoice-fields" hidden><div class="form-grid">${field('שם לחיוב / חברה','invoiceName')}${field('מספר זיהוי / מס','invoiceTax')}</div>${field('כתובת מלאה לחיוב','invoiceAddress')}</div><label style="margin-top:18px">בקשות והערות<textarea name="remarks" rows="2"></textarea></label></section><section class="panel"><h2>מה יקרה בלחיצה?</h2><p class="small">הזמנה חדשה תישלח ישירות לחברת ההשכרה שנבחרה, עם העתק לעידן. ההזמנה תופיע במערכת ותמתין לאישור.</p><div class="hint gold">שליחת הבקשה אינה אישור זמינות. ההזמנה תסומן כמאושרת לאחר שעידן יעדכן את אישור החברה.</div><label class="check"><input type="checkbox" required>בדקתי את פרטי הנסיעה, הנהגים והתנאים של האפשרות שבחרתי.</label></section><div class="actions">${button('חזרה להצעה','review')}<button class="button primary">בדיקת הפרטים לפני שליחה ←</button></div></form>`;}
function listPage(kind){return `${heading('המרחב האישי',kind==='quotes'?'ההצעות שלי':'ההזמנות שלי','רק פניות והזמנות שנוצרו דרך החשבון שלכם.',button('＋ הצעה חדשה','trip',true))}<section class="panel"><label class="search">חיפוש לפי מספר או שם<input id="history-search" placeholder="מספר הצעה, הזמנה או שם הלקוח"></label>${history(kind)}<p class="small muted">הזמנות ישנות שעידן יצר מחוץ לקבינט אינן מוצגות כאן.</p></section>`;}
function detail(isNew){return `${heading('מעקב הזמנה',isNew?'DEMO-R-0083':'DEMO-R-0082','פרטי ההזמנה והעדכונים במקום אחד.',badge(isNew?'ממתינה לאישור':'מאושרת',isNew?'gold':'green'))}<div class="split"><div><section class="panel"><h2>פרטי ההזמנה</h2>${tripSummary()}<div class="row between"><div><h3>${isNew?esc(state.bookingCompany||'One Rent'):'CarFree'}</h3><p class="small muted">${esc(isNew?(state.driver||'נהג לדוגמה'):'נהג לדוגמה')} · רכב לפי הקבוצה שנבחרה</p></div><span class="price-placeholder">לפי ההצעה המאושרת</span></div></section><section class="panel"><h2>מעקב ועדכונים</h2><div class="timeline"><p>הבקשה נשמרה בקבינט<small>פרטי הנסיעה והנהגים מרוכזים בהזמנה.</small></p><p>נשלחה בקשה לחברת ההשכרה<small>עידן קיבל העתק עם סימון השותף.</small></p><p>${isNew?'ממתינים לאישור החברה':'עידן עדכן: ההזמנה מאושרת'}<small>${isNew?'האישור יופיע כאן לאחר עדכון במערכת.':'מספר החברה והוואוצ׳ר יוצגו לאחר חיבור למערכת.'}</small></p>${state.request?'<p>בקשת השינוי / הביטול הועברה לעידן<small>ההזמנה הקיימת לא שונתה.</small></p>':''}</div></section><section class="panel"><h2>צריך לשנות או לבטל?</h2><p class="small muted">כל שינוי וביטול מטופלים דרך עידן. ההזמנה הנוכחית נשארת כפי שהיא עד לקבלת אישור.</p><div class="row"><button class="button" data-action="request-change">בקשת שינוי מעידן</button><button class="quiet" data-action="request-cancel">בקשת ביטול מעידן</button></div></section></div><aside class="side-note"><img src="idan-portrait.jpg" alt="עידן"><h3>אני מכיר את ההזמנה שלכם.</h3><p>שלחו את השינוי מכאן. פרטי ההזמנה יצורפו אוטומטית, בלי להעתיק שוב תאריכים ומספרים.</p></aside></div>`;}
function manual(){return `${heading('יש עם מי לדבר','כשצריך בדיקה אישית — אני כאן.','בקשה מורכבת עוברת לעידן עם כל הפרטים שכבר מילאתם.')}<div class="split"><section class="panel">${state.manual?'<div class="hint green">הבקשה נשמרה להמחשה · ממתינה לבדיקה של עידן</div>':''}${tripSummary()}<form id="manual-form"><label>מה צריך לבדוק?<textarea name="message" rows="5" required placeholder="מסלול מיוחד, תנאי נהג, בקשה שלא מצאתם...">${state.manualReason||''}</textarea></label><p class="small muted" style="margin-top:12px">הפנייה שומרת את הנסיעה והבחירות שלכם. לא תישלח הזמנה לחברה עד שהמקרה ייבדק.</p><div class="actions"><a href="#home">חזרה למרחב</a><button class="button primary">העברת הבקשה לעידן ←</button></div></form></section><aside class="side-note"><img src="idan-portrait.jpg" alt="עידן"><h3>עידן · הנציג שלכם</h3><p>המטרה היא לפתור את השאלה, בלי התכתבות ארוכה ובלי למלא שוב את כל הטופס.</p><p>לאחר הבדיקה תופיע תשובה והצעה מתאימה.</p></aside></div>`;}
function owner(){return `${heading('ניהול שותפים · עידן','כל הקבינטים, מבט אחד.','רק אתה יוצר גישה. אפשר לפתוח כל קבינט ולעבוד עם הפניות שלו.','<button class="button primary" data-action="new-partner">＋ יצירת גישה לשותף</button>')}<div class="hint gold">תצוגת עיצוב של הרשאות הבעלים. במערכת הפעילה כל פעולה תישמר עם זהות המבצע.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>שותף</th><th>פרטי קשר</th><th>הצעות</th><th>הזמנות</th><th>גישה</th><th></th></tr></thead><tbody>${[1,2].map(i=>`<tr><td><strong>${names[i]}</strong><small>תנאים לפי החשבון</small></td><td><bdi>partner${i}@example.invalid</bdi><br><small>הטלפון נשמר בפרופיל</small></td><td>1</td><td>${i===1?'1':'0'}</td><td>${badge('פעילה','green')}</td><td><button class="quiet" data-open-partner="${i}">פתיחת הקבינט ←</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>בקשות שדורשות טיפול</h2><div class="row between"><div><strong>שינוי / ביטול הזמנה</strong><p class="small muted">מגיעים רק אליך, עם פרטי ההזמנה והשינוי המבוקש.</p></div>${badge(state.request?'בקשה חדשה להמחשה':'אין בקשות חדשות')}</div><hr style="border:0;border-top:1px solid #e8edf3;margin:18px 0"><div class="row between"><div><strong>חישובים לא סטנדרטיים</strong><p class="small muted">הנסיעה והבחירות נשמרות. אפשר להשלים ידנית ולהחזיר תשובה.</p></div>${badge(state.manual?'בקשה חדשה להמחשה':'אין בקשות חדשות')}</div></section><section class="panel"><h2>עותק קבוע, זיהוי ברור.</h2><p>כל מייל מהקבינטים מועתק אל <bdi>${OWNER}</bdi>.</p><p class="small muted">בתוכנית ובמייל מופיע שם השותף. המחירים נשענים על התנאים שכבר חלים בהצעות הידניות.</p></section>`;}
function render(){const route=location.hash.slice(1)||'home';const pages={home,trip,options,review,book:bookingForm,quotes:()=>listPage('quotes'),bookings:()=>listPage('bookings'),detail:()=>detail(false),'detail-new':()=>detail(true),manual,owner};if(route==='owner')state.owner=true;$('#main').innerHTML=(state.owner&&route!=='owner'?`<div class="owner-banner">עידן · צפייה בקבינט של ${names[state.partner]} <a href="#owner" style="margin-inline-start:16px">חזרה לניהול השותפים ←</a></div>`:'')+(pages[route]||home)();$('#partner-name').textContent=names[state.partner];document.querySelectorAll('.sidebar>a,.header nav>a').forEach(a=>a.classList.toggle('active',a.hash===location.hash));if(route==='options')syncPicks();}
const sourceCategory=new Map();
function syncPicks(){document.querySelectorAll('[data-pick]').forEach(input=>{const id=input.dataset.pick;const selected=state.selected.has(id);const elsewhere=selected&&sourceCategory.has(id)&&String(sourceCategory.get(id))!==input.dataset.category;input.checked=selected;input.disabled=elsewhere;const note=input.closest('tr').querySelector('[data-already]');note.hidden=!elsewhere;});if($('#selected-count'))$('#selected-count').textContent=`${state.selected.size} אפשרויות נבחרו`;}
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-open-partner]');if(!el)return;if(el.dataset.openPartner){state.partner=Number(el.dataset.openPartner);navigate('home');return;}switch(el.dataset.action){case 'profile':showDialog(`<h2>הפרטים והתנאים שלכם</h2><p>${names[state.partner]}</p><p><bdi>partner@example.invalid</bdi></p><p class="muted">הטלפון ותנאי החשבון יוזנו מראש על ידי עידן. לשינוי פרטי החשבון פונים אליו.</p>`);break;case 'review':if(!state.selected.size)toast('בחרו לפחות אפשרות אחת.');else navigate('review');break;case 'expiry':state.expired=!state.expired;render();break;case 'book':{const pick=$('[name="book-choice"]:checked');if(!pick){toast('בחרו אפשרות אחת להזמנה.');return;}state.bookingCompany=choices.find(o=>o.id===pick.value).company;if(state.expired&&pick.value==='one-suv'){showDialog('<h2>נדרש חישוב מחיר חדש</h2><p>עברו 7 ימים ומחירון החברה עודכן. במערכת המחוברת יוצגו המחיר החדש וההפרש לאישורכם לפני ההזמנה.</p><p class="hint">המצגת אינה ממציאה מחיר חלופי ואינה יכולה לאשר מחיר אמיתי.</p>');return;}navigate('book');break;}case 'request-change':case 'request-cancel':{const cancel=el.dataset.action==='request-cancel';showDialog(`<h2>${cancel?'בקשת ביטול':'בקשת שינוי'} לעידן</h2><form id="change-form"><label>מה מבקשים ${cancel?'לבטל':'לשנות'}?<textarea name="message" rows="4" required></textarea></label><p class="hint">ההזמנה הקיימת נשארת בתוקף עד לאישור. הפנייה מועברת לעידן בלבד.</p><button class="button primary">שליחת הבקשה לעידן</button></form>`);break;}case 'new-partner':showDialog(`<h2>גישה חדשה לשותף</h2><form id="access-form"><div class="form-grid">${field('שם השותף','name','','text',true)}${field('מייל','email','','email',true)}${field('טלפון','phone','','tel',true)}<label>תנאים קיימים<select><option>כמו בהצעות הידניות לשותף</option></select></label></div><p class="hint">רק עידן יוצר גישה. השותף יקבל הזמנה להגדרת סיסמה אישית.</p><button class="button primary">הדמיית יצירת גישה</button></form>`);break;}});
document.addEventListener('change',event=>{const e=event.target;if(e.matches('[data-pick]')){if(e.checked){state.selected.add(e.dataset.pick);sourceCategory.set(e.dataset.pick,e.dataset.category);}else{state.selected.delete(e.dataset.pick);sourceCategory.delete(e.dataset.pick);}syncPicks();}if(e.id==='cross-border')$('#countries-wrap').hidden=e.value!=='yes';if(e.name==='recipient'){$('#client-email').hidden=e.value!=='both';$('[name="clientEmail"]').required=e.value==='both';}if(e.id==='additional-driver'){$('#second-driver').hidden=!e.checked;$('[name="secondDriver"]').required=e.checked;}if(e.id==='invoice-toggle'){$('#invoice-fields').hidden=!e.checked;['invoiceName','invoiceAddress'].forEach(n=>$(`[name="${n}"]`).required=e.checked);}});
document.addEventListener('input',event=>{if(event.target.id==='history-search'){const q=event.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target;if(!f.checkValidity()){f.reportValidity();return;}const data=new FormData(f);if(f.id==='trip-form'){state.trip={...state.trip,...Object.fromEntries(data)};const date=s=>{const m=/^(\d{2})\.(\d{2})\.(\d{4})$/.exec(s);if(!m)return NaN;const d=new Date(+m[3],+m[2]-1,+m[1]);return d.getDate()===+m[1]&&d.getMonth()===+m[2]-1?d.getTime():NaN;};const start=date(state.trip.from),end=date(state.trip.to);if(!Number.isFinite(start)||!Number.isFinite(end)||end<start||(end===start&&state.trip.returnTime<=state.trip.time)){toast('בדקו את התאריכים והשעות. תאריך בפורמט יום.חודש.שנה; החזרה לאחר הקבלה.');return;}if(!data.has('driverOk')||!data.has('cardOk')||!data.has('borderOk')||data.get('pickup').includes('פראג')||data.get('dropoff').includes('פראג')){state.manualReason='בדיקת תנאי נהג / כרטיס / מסלול מיוחד. הפרטים שמולאו נשמרו.';navigate('manual');return;}navigate('options');}if(f.id==='send-form')toast('הדמיה בלבד: ההצעה מוכנה לשליחה לנמענים שנבחרו, עם העתק לעידן. לא נשלח מייל.');if(f.id==='book-form'){state.driver=data.get('driver');state.invoice=data.get('invoiceName')||'';state.bookingData=Object.fromEntries(data);navigate('confirm');}if(f.id==='manual-form'){state.manual=true;toast('נשמרה פנייה להמחשה · ממתינה לבדיקה של עידן.');render();}if(f.id==='change-form'){state.request=true;$('#dialog').removeAttribute('open');render();toast('בקשת הדגמה הועברה לעידן. ההזמנה עצמה לא שונתה.');}if(f.id==='access-form'){$('#dialog').removeAttribute('open');toast('הדמיית יצירת גישה בלבד. לא נוצר משתמש ולא נשלח מייל.');}});
$('#owner-mode').addEventListener('click',()=>{state.owner=true;navigate('owner');});
$('.close').addEventListener('click',()=>{if(typeof $('#dialog').close==='function')$('#dialog').close();else $('#dialog').removeAttribute('open');});
const tour=[
 ['home','Личный кабинет без лишних действий','Контакты и условия уже сохранены. Партнёр видит свои оферты и заказы. Портрет и подсказки напоминают, что за системой стоит Идан.'],
 ['trip','Один раз вводим поездку','Даты дд.мм.гггг, время каждые 30 минут. Декларации заранее отмечены. Партнёр меняет ответы, если условия отличаются.'],
 ['options','Выбираем варианты, а не заполняем таблицы','Все 14 категорий доступны. Аккордеоны раскрываются по необходимости. Одна группа не дублируется в разных категориях. Цены в дизайне не вымышлены: до подключения показана подпись «по ценнику».'],
 ['review','Как в основной программе: заказ из конкретного варианта','У каждого пронумерованного варианта своя кнопка «Выбрать и создать заказ». Не нужно выбирать радиокнопку и искать общую кнопку внизу. Отправка оферты по почте вынесена отдельно.'],
 ['book','Выбранная машина всегда перед глазами','Компания и группа переносятся из оферты. Остаётся заполнить водителей и инвойс. Дальше — отдельная проверка перед отправкой фирме.'],
 ['confirm','Перед отправкой всё видно','Один экран: выбранная фирма и группа, поездка, водители и инвойс. Сначала исправляем при необходимости, затем отправляем новый заказ фирме с обязательной копией Идану.'],
 ['detail','Отправлено — ещё не подтверждено','Ожидание и подтверждение разделены. Подтверждение отмечает Идан в основной программе. Изменение и отмена направляются только Идану, исходный заказ сохраняется.'],
 ['manual','Нестандартный случай не теряется','Поездка и выбранные варианты передаются Идану вместе с вопросом. Статус показывает, что запрос ожидает ручного рассмотрения.'],
 ['owner','У Идана полный доступ','Только Идан создаёт доступ. Он открывает кабинет каждого партнёра и видит запросы. Письма помечены именем партнёра; постоянная копия — idan.caliber@gmail.com.']
];
function showTour(i){state.tour=Math.max(0,Math.min(i,tour.length-1));const t=tour[state.tour];document.body.classList.add('presenting');$('#tour').hidden=false;$('#tour-count').textContent=`${state.tour+1} / ${tour.length} · ДИЗАЙН КАБИНЕТА` ;$('#tour-title').textContent=t[1];$('#tour-copy').textContent=t[2];$('#tour-prev').disabled=state.tour===0;$('#tour-next').textContent=state.tour===tour.length-1?'Завершить':'Далее →';navigate(t[0]);}
$('#present').addEventListener('click',()=>showTour(0));$('#tour-prev').addEventListener('click',()=>showTour(state.tour-1));$('#tour-next').addEventListener('click',()=>state.tour===tour.length-1?closeTour():showTour(state.tour+1));function closeTour(){$('#tour').hidden=true;document.body.classList.remove('presenting');state.tour=-1;}$('#tour-close').addEventListener('click',closeTour);
const originalRender=render;
function restoreBookingFields(){const data=state.bookingData;if(!data)return;for(const [name,value] of Object.entries(data)){const field=document.querySelector('#book-form [name="'+name+'"]');if(field&&field.type!=='checkbox')field.value=value;}for(const [toggle,name] of [['additional-driver','secondDriver'],['invoice-toggle','invoiceName']]){const field=document.getElementById(toggle);if(field&&data[name]){field.checked=true;field.dispatchEvent(new Event('change',{bubbles:true}));}}}
function selectedBookingSummary(){const o=choices.find(o=>o.id===state.bookingOption)||choices.find(o=>state.selected.has(o.id));return o?`<div class="chosen-vehicle"><span class="status green">האפשרות שנבחרה מההצעה</span><h2>${o.company} · ${o.group}</h2><p class="model">${o.models}</p><a href="#review" class="small">בחירת אפשרות אחרת</a></div>`:'';}
function bookingConfirmation(){const d=state.bookingData||{};return `${heading('בדיקה אחרונה לפני שליחה','הכול נכון? אפשר לשלוח.','הבקשה תישלח לחברה שמופיעה כאן, עם העתק קבוע לעידן.')}${selectedBookingSummary()}${tripSummary()}<section class="panel"><h2>פרטי הנהגים ואיש הקשר</h2><div class="form-grid"><p><span class="muted small">נהג ראשי</span><br><bdi>${esc(d.driver||'טרם הוזן')}</bdi></p><p><span class="muted small">נהג נוסף</span><br><bdi>${esc(d.secondDriver||'ללא')}</bdi></p><p><span class="muted small">טלפון</span><br><bdi>${esc(d.phone||'טרם הוזן')}</bdi></p><p><span class="muted small">מייל</span><br><bdi>${esc(d.email||'טרם הוזן')}</bdi></p></div>${d.invoiceName?`<h3>פרטי חשבונית</h3><p>${esc(d.invoiceName)} · ${esc(d.invoiceTax||'')}<br>${esc(d.invoiceAddress||'')}</p>`:''}${d.remarks?`<h3>הערות לחברה</h3><p>${esc(d.remarks)}</p>`:''}<p class="hint">מחיר ופיקדון: לפי האפשרות המחושבת בהצעה. בתצוגת העיצוב אין מחיר מומצא.</p></section><section class="panel"><h2>השליחה</h2><p>אל חברת ההשכרה: <strong>${esc(state.bookingCompany||'החברה שנבחרה')}</strong></p><p>העתק לעידן: <bdi>${OWNER}</bdi></p><p class="hint gold">לאחר השליחה: ממתינה לאישור. אישור הזמינות יופיע לאחר שעידן יעדכן את תשובת החברה.</p></section><div class="actions"><a class="button" href="#book">חזרה לתיקון הפרטים</a><button class="button primary" data-action="confirm-booking">שליחת בקשת הזמנה ל־${esc(state.bookingCompany||'חברה')}</button></div>`;}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='book-option'){const o=choices.find(o=>o.id===el.dataset.option);if(!o||!state.selected.has(o.id))return;if(state.expired&&o.id==='one-suv'){showDialog('<h2>נדרש חישוב מחיר חדש</h2><p>חלפו 7 ימים ומחירון החברה עודכן. נציג מחיר חדש לאישור לפני הזמנה. שאר החברות אינן מושפעות.</p>');return;}state.bookingOption=o.id;state.bookingCompany=o.company;navigate('book');}if(el.dataset.action==='confirm-booking'){if(!state.bookingData){toast('השלימו את פרטי הנהגים לפני שליחה.');navigate('book');return;}state.booked=true;state.bookingPartner=state.partner;navigate('detail-new');toast('הדמיה בלבד: נוצרה בקשה הממתינה לאישור. לא נשלח מייל אמיתי.');}});
render=function(){if(location.hash==='#confirm'){$('#main').innerHTML=bookingConfirmation();return;}if((location.hash.slice(1)||'home')==='login'){$('#main').innerHTML=login();return;}originalRender();if(location.hash==='#book')restoreBookingFields();};
document.addEventListener('submit',event=>{if(event.target.id==='login-form'&&event.target.checkValidity()){navigate('home');toast('כניסת הדגמה בלבד. לא נבדקה ולא נשמרה סיסמה.');}});
tour.unshift(['login','Личный вход, открытый Иданом','Самостоятельной регистрации нет. Идан заранее сохраняет контакты и условия, партнёр входит со своим паролем. В демонстрации настоящие пароли вводить не нужно.']);
window.addEventListener('hashchange',render);render();if(new URLSearchParams(location.search).has('presentation'))showTour(0);
